import java.io.*; public class LanguageWorker{static final int KEY=0xB9;public static void main(String[]a)throws Exception{BufferedReader r=new BufferedReader(new InputStreamReader(System.in));BufferedWriter w=new BufferedWriter(new OutputStreamWriter(System.out));String s;while((s=r.readLine())!=null){if(s.equals("PING")){w.write("PONG\n");w.flush();continue;}if(s.equals("QUIT"))break;if(s.matches("^[ED] [0-9A-Fa-f]*$")){String h=s.substring(2);StringBuilder o=new StringBuilder();for(int i=0;i<h.length();i+=2)o.append(String.format("%02x",Integer.parseInt(h.substring(i,i+2),16)^KEY));w.write(o+"\n");w.flush();}else{w.write("ERR\n");w.flush();}}}}
